@misc{nationalaeronauticsandspaceadministration1969,
  author = {{National Aeronautics and Space Administration}},
  title = {{Apollo} 11 air-to-ground voice communications},
  year = {1969},
  language = {en},
  note = {SPDF conformance document: seven transmissions transcribed literally from NASA's Apollo 11 Technical Air-to-Ground Voice Transcription (Manned Spacecraft Center, Houston, 1969). Times are ground elapsed time (GET) in seconds, as in the transcription; each span ends at the next later transmission. The recording itself is not included and source_sha256 is a placeholder; word timings are spread evenly over each span, not measured.}
}
